# NUX NEK-100 DSP firmware V1.0.7 — community map (our own descriptions, no vendor code).
# Addresses are 16-bit word addresses (file word index == code address).
# Descriptions: (C) confirmed on hardware, (H) inferred from code, unmarked = strong evidence from code.

firmware NEK100_DSP_V1.0.7 sha256 b072b6bda1971697ebb0624cd11a05dac0bb81ce9996cabce2092c1f1e3bffc0
device   "NUX NEK-100"
input    NEK100_DSP_V1.0.7.bin
output   NEK100_DSP_V1.0.7B_mod.bin
download https://nuxaudio.com/product/nek100/
defaults boot_preset touch_off sustain_in_preset version_tag octave_per_part extra_menu
optional polish_font lang_pl custom_voices telemetry battery_percent touch_custom doom_demo sustain_midi_out battery_gauge

code    0x00400 0x0f0a3     ; code bank 0
code    0x10400 0x128ab     ; code bank 1 (reached how? unknown)
ramdata 0x155f7 0x17f23     ; initialised data, copied to RAM address 0 at boot
pool    0x09ad4 0x09bd4     ; unreferenced function (no calls, branches or pointers) — patch code goes here (C)
pool    0x062f3 0x06558     ; unreferenced function, same checks (C: polish_font runs here)
pool    0x0f0b0 0x0fff0     ; 0xffff filler after the code of bank 0, loaded into program memory (C: probe words at 0xf0b0 and 0xffe0 read back on the device)
pool    0x08e5a 0x08eff     ; C-library call wrappers (0x810d/0x820d .. epilogue) that nothing calls: no word of the image equals an address inside, no known branch comes in; checked: the telemetry runs here
pool    0x09169 0x091fb     ; more of them, same checks; checked: telemetry runs here
farpool 0x19720 0x19940     ; 0xffff padding in front of bank-1 code at 0x1994e (no reference into it), reached by a far call (d6c9) (C: far_test code ran here on the device)
farpool 0x1a280 0x3ffc0     ; past the end of the official file (0x1a280 words), up to the 512 KB firmware partition; the file grows (C: a 0x1a2c0-word file flashed, code at 0x1a280 ran)
glyphs  0x12cf7 0x1348f 243 ; glyph/image table (8 words each: u32 byte offset, size, width, height) + bitmaps
soundbank NEK100_SBANK_V1.0.4 sha256 59d5c23ba8269e21c231195280ef8c6255ced890a5c8977868c9aba83313b646 template 479 1 loop 48 0 piano 1 223 pianomods 803fffff 803f2dfd sustain 1 9 grander 1 66 0x70 granderfall 0.10:1.3,0.11:4.4,0.12:1.7,0.13:2.5,0.14:1.3,1.10:1.3,1.11:4.4,1.12:1.7,1.13:2.5,1.14:1.3,2.11:2,2.12:1.6,2.13:1.3,2.14:1.7,3.11:2,3.12:1.6,3.13:1.3,3.14:1.7,4.11:2,4.12:1.6,4.13:1.3,4.14:1.7,5.11:2,5.12:1.6,5.13:1.3,5.14:1.7,6.11:2.2,6.12:1.3,6.13:1.4,6.14:1.7,7.11:2.2,7.12:1.3,7.13:1.4,7.14:1.7 end 0x7000000 ; added instruments copy the settings of 479.Shamisen's zone 1 (C: quick attack, follows the keyboard, decays), those with loops 48.Organ 10's zone 0 (C: holds while the key is held), pianos (GM programs 0..7) 1.Grand Piano's zone 223 (layer velocity 103-127, keys 59-62, stereo; C: closer to the SoundFont than 3.Bright Piano's zone 8, 2.Standard Piano or the others) with velocity modulators covering 0-127 (C: the Grand layer's own react only within 103-127): volume as 3.Bright Piano's zone 8's (C: follows velocity), filter open at soft hits too (C: closest to the SoundFont of 1a, 00, 80, ff); the longer sustain option slows 1.Grand Piano's decay, its zones falling faster than 9 s first set to 9 s (its velocity 75-84 layer's high keys: 2-3 s); Grander Piano reshapes 1.Grand Piano's samples from F#4 (key 66) up, one-shots there (C, 2026-10-19: from F#4 up short loops are heard), its header points to a 0x70-byte velocity-layer block; granderfall (soundbank.grander_fall_table): its zones from C#3 to F4 fall slower so that the sound's length grows evenly from C3 (as the vendor's) to F#4 (C, 2026-10-20: with octave -1 the reshaped keys rang far longer than those below F#4); the soundbank partition ends at flash word 0x7000000 (223 MiB of SBank2K)

# --- startup / system ------------------------------------------------------------------------
func  0x005f8 main                    ; init_all(), then forever main_loop_tick()
func  0x007dd tick_10ms               ; (C: 10 ms, 6000 ticks of idle measured as ~60 s) periodic timer callback: idle counter, power key, USB, popups
func  0x00948 power_off               ; drops the power/amp/LCD output pins and loops forever
func  0x00958 power_key_poll          ; input 0x28e0 bit 0x400 held 50 ticks -> power_off; idle_ticks >= 180000 (30 min) -> power_off (C: auto off, on battery); extra_menu: limit per power source, also on cable (C)
func  0x0078a usb_poll                ; input 0x28e2 bit 1 (H: the NUX dongle plugged in): dongle_state 0 -> after ~1 s 1: nux_identity for 10 ticks -> 2: wait -> 3: dongle_config
func  0x00b01 battery_tick            ; per tick: input 0x28e0 bit 2 low -> power_src=2 (charger plugged, checked: ADC rises in those windows; also zeroes idle_ticks, so no auto off on cable), else 1; low battery: blink icon ~14 s then power_off
func  0x00a25 battery_adc_sample      ; one ADC reading (10 bit) into a 32-entry ring at 0x2a1a
func  0x00aa4 battery_average         ; averages the ring sums into batt_adc; on battery counts readings below batt_levels[0]
func  0x00a63 charge_full_poll        ; output 0xe0 bit 3 low, wait, input 0x28e0 bit 4 -> charge_full
func  0x055b2 draw_battery            ; status bar battery at x=0x70 (glyph 0xbd), lightning 0xc4 at x=0x6b on cable, bars from batt_adc vs batt_levels
func  0x02185 mcu_cc                  ; CC from the MCU on channel 16: tempo, style state, panel keys 0x50.., dial 0x70, version 0x7d/0x7e, ready 0x7f
func  0x0385f key_event               ; (key, state) panel key -> per-screen handlers; resets idle_ticks
func  0x00c88 init_all                ; calls ~25 init routines, boot_presets near the end
func  0x07c90 main_loop_tick
func  0x02774 tasks_create            ; creates the RTOS tasks below via task_create
func  0x0c591 task_create             ; r2 = message queue, r5 = stack, r7 = entry point
func  0x0c5aa task_send_msg           ; r2 = destination queue
func  0x0282b task_key_events         ; task(msg_type @fp+14, msg @fp+15); type 0 = MIDI event from the keys (C)
func  0x02d3e task_ext_events         ; task for events coming from outside (H: the dongle UART's RX, the same port as dongle_q)

# --- MIDI ------------------------------------------------------------------------------------
func  0x01330 synth_send              ; (status|channel, d1<<8|d2) -> internal synthesizer
func  0x01340 midi_parse_byte         ; MIDI byte parser with running status
func  0x020d8 send_internal_cc        ; (cc, value): CC on channel 1 into the port-1 queue (to the MCU, H)
func  0x02e40 midi_out_packet         ; (port, packet): port 1 -> queue at port1_q, port 2 -> port2_out_packet
func  0x02cbe port2_out_packet        ; (packet) USB-MIDI packet, high word CIN << 8 | status, low word d1 << 8 | d2 -> packet_to_bytes -> dongle_q: the NUX dongle's way out (H strong: the dongle's NUX SysEx go the same way; not USB, tele5-7)
func  0x062cc usb_out_packet          ; (packet) the same packet to USB MIDI (C); sustain_switch and notes call it and port2_out_packet, pitch bend and cc_out (pedals, CCs per part) only this one
func  0x02e5b midi_out_byte
func  0x0be50 port1_queue_put         ; put one byte into the port-1 ring buffer
func  0x0be88 port1_put_usbpacket     ; split a USB-MIDI packet (CIN -> length) into port1_queue_put calls
func  0x03377 sustain_switch          ; (v) v = 0: CC64 0 on parts 0..2; else CC64 sustain_cc64[k] (the Sustain soft key, panel_buttons 0x3428; C: k = 0..2 on USB and the dongle)
label 0x033c4 sustain_switch_on       ; sustain_switch on: for k in 0..2: CC64 sustain_cc64[k] to synth_send, usb_out_packet and port2_out_packet (0x33b3) (not the pedal: mcu_pedal -> pedal_in -> cc_out)
label 0x02242 mcu_pedal               ; mcu_cc, controller 0x74 from the MCU (0x21a8) = the sustain pedal: value 0 up, else 127 -> pedal_in(0, v, 0)
func  0x01204 pedal_in                ; (pedal 0..2, v, ch): on a change of pedal_state (hysteresis 7, >= 0x78 -> 127) cc_all_parts(pedal_cc[pedal], v, ch)
label 0x0dfb6 pedal_cc 3              ; ldc table: 64, 67, 66 (sustain, soft, sostenuto)
var   0x02a3c pedal_state 3           ; last value of each pedal (pedal_in)
func  0x00e60 cc_all_parts            ; (ctrl, v, ch): cc_out for every part (0..part_count-1) that takes this controller (bit maps 0x2ac0, 0x2c67; 1, 64, 66, 67 apart)
func  0x00de0 cc_out                  ; (part, ch, ctrl, v): CC to synth_send and usb_out_packet (0x0e5d), only on a change (cache 0x2ad8); 64 scaled by the part's table at 0x2c66 (H)
var   0x02c5b part_count              ; (H) parts in use: loop bound of cc_all_parts and others
func  0x01561 packet_to_bytes         ; (packet, buf) -> number of MIDI bytes (case by CIN: ldc table 0xdfb7, jump c749); no state
func  0x02cae dongle_q_init           ; dongle_q = 0x312c, ring set up (0x7a40); from tasks_create after the UART (0x30e8)
func  0x02cb7 dongle_put_byte         ; (byte) -> dongle_q (the NUX SysEx senders)
func  0x02d32 dongle_tx_next          ; one byte of dongle_q to the UART (io_events, event bit 2)
var   0x0332c dongle_q                ; pointer to the byte ring at 0x312c (dongle UART TX)
func  0x07a18 ring_put                ; (r2 ring, r7 byte) put a byte, start the transmitter when idle (H; hand-written)
func  0x07ab0 uart_tx_next            ; (r2 ring) TX ready (I/O 0x2838): next byte out; 2 = ring empty (H)
func  0x00cd5 io_events               ; (H) task loop: event bit 1 -> 0xbe63, bit 2 -> dongle_tx_next, bit 3 -> USB (0xbf70)
func  0x006fd nux_identity            ; F0 4E 55 58 04 00 08 "NEK-100" 00 F7 -> dongle_q (usb_poll, dongle_state 1)
func  0x0066f nux_cmd0                ; (v) F0 4E 55 58 00 .. F7, 0 or 1 by v -> dongle_q
func  0x0063d nux_cmd6                ; (v) F0 4E 55 58 06 .. F7 -> dongle_q
func  0x006a1 nux_cmd7_8              ; (v) F0 4E 55 58 .. F7 with 08 or 07 by v -> dongle_q
func  0x006d4 nux_cmd2                ; F0 4E 55 58 02 00 1F F7 -> dongle_q
func  0x0076c dongle_config           ; dongle_state 3, up to 10 times: nux_cmd0/6/7_8 with dongle_flag (+ nux_cmd2)
func  0x00768 dongle_config_again     ; dongle_cfg_n = 0 (unplugged, dongle_flag changed)
var   0x00004 dongle_flag             ; (H) a menu toggle (0x3518, 0x3ac0), sent to the dongle by dongle_config
var   0x00014 dongle_cfg_n            ; dongle_config sends so far (stops at 10)
var   0x00016 dongle_state            ; usb_poll's state, 0..3
func  0x0bee8 irq_off                 ; (H) I/O 0x36 &= ~0xc00, returns the old value (usb_out_packet)
func  0x0c238 usb_put_packet          ; (H) through the pointer at 0x73e5 into the USB ring 0x73ec
func  0x0d6d0 synth_write             ; (H) synth_send's driver

# --- presets ---------------------------------------------------------------------------------
func  0x02290 collect_preset          ; (ptr) current settings -> 31-word preset
func  0x02370 apply_preset            ; (ptr) 31-word preset -> settings, applies them (field 12 = touch)
func  0x02492 flash_write_words
func  0x024c4 preset_write_flash      ; (ptr, n): 31 words to flash page 0x701+n (header: page 0x700). Pages are erased one by one (DataFlash commands 0x81/0x50/0x84/0x88/0xe8); nothing else in the firmware uses this flash. extra_menu: n = 5 (page 0x706) holds the Autosave settings (C)
func  0x024f9 presets_read_flash      ; reads the 3-word preset header from flash
func  0x02523 presets_load_all        ; reads the 5 user presets from flash into user_presets
func  0x02565 save_user_preset        ; (n): collect_preset + write to flash
func  0x0258c load_user_preset        ; (n = 0..4): current_preset = n, apply_preset(user_presets + 31n) (C)
func  0x025a3 load_factory_preset     ; (n): apply_preset(factory_presets + 31n)
func  0x025ba presets_factory_reset   ; copies factory presets to user presets, sends CC 0x7c
func  0x025e7 boot_presets            ; init flash, read presets, ends with load_factory_preset(0) (C)
func  0x07b6d flash_put_word
func  0x07b77 flash_get_word

