# --- RAM variables ---------------------------------------------------------------------------
var   0x0000b idle_ticks 2            ; 32-bit, +1 per tick, zeroed by every key, button, dial and MIDI event
var   0x00006 power_src               ; 0 = no battery seen at power-on (logic off), 1 = on battery, 2 = charger plugged (checked)
var   0x00007 charge_full             ; on cable: 1 = (H) charger reports full, 0 = charging
var   0x00008 batt_adc                ; averaged battery ADC (10 bit); < 0x190 at power-on -> power_src = 0
var   0x0001c batt_low                ; 1 after 15 readings below batt_levels[0] on battery: icon blinks, power_off after 1400 ticks
var   0x02809 batt_levels 6           ; ADC thresholds of the battery bars (+0x12 while charging)
var   0x0000f ui_part                 ; (H) index of the part being edited (0 = main voice)
var   0x00069 factory_presets 155     ; 5 x 31 words, initialised data
var   0x00145 volume                  ; (H, strong) master VOL 0..10 shown on the main screen (glyph 0xe9); param handler 0x3fa4 sends vol*127/10; saved in presets
var   0x00158 octave                  ; Octave 0..2 = -1/0/+1 (C: menu), read through param_get, saved in presets
var   0x00144 touch                   ; Touch 0..4 = LIGHT2 LIGHT1 NORMAL HARD1 HARD2 (C); sent to MCU as CC 0x32
var   0x0015d sustain_on              ; Sustain key state 0/1 (init 0, not in presets); drawn as soft key 2 (glyphs 0xf1/0xf2)
var   0x0015e sustain_cc64 4          ; CC64 value per part sent by the Sustain key (sustain_switch), defaults 90,64,64,64 (C)
var   0x0011c voice_banks 38        ; (soundbank bank, number of sounds) pairs in sound number order, ends with 0, 0 (C: added instruments go where this says)
var   0x0233c sound_names 600         ; pointers to the 500 sound names, then the 100 demo song names
var   0x025bc effect_names 5          ; pointers to the modulation effect names
var   0x02617 section_names 9         ; pointers to style section names (PITCH:, CHANGE, ROLL, BRIDGE1..4, ENDING1..2)
var   0x02745 style_names 20          ; pointers to the 20 style names
var   0x03a0d screen                  ; current screen: 11 = Sustain (MAIN/DUAL/SPLIT keys), 12 = Octave
var   0x0275c str_off                 ; "OFF"
var   0x027c7 touch_names 5           ; pointers to "LIGHT2".."HARD2"
var   0x027dc reverb_names 4          ; pointers to "OFF","ROOM","HALL","PLATE"
var   0x03026 user_presets 155        ; 5 x 31 words, loaded from flash
var   0x030c1 presets_header 2        ; read from flash with current_preset; +1 = 0x4e5b when valid; [0] unused by the firmware (stock 1): extra_menu keeps its settings there (C)
var   0x030c3 current_preset          ; last loaded preset number (also written to flash)
var   0x07276 port1_q_head
var   0x07277 port1_q_tail

